
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const years = new Date().getFullYear() - 2005;
  const YEARS = years;
  document.querySelectorAll('.js-years').forEach(el => el.textContent = years);
  document.querySelectorAll('.js-count').forEach(el => el.dataset.to = years);
  document.getElementById('year').textContent = new Date().getFullYear();

  // Header style on scroll + mobile contact bar
  const header = document.getElementById('header');
  const bar = document.getElementById('mobile-bar');
  // The contact bar appears once the page's first section (the hero) has scrolled away
  const onScroll = () => {
    header.classList.toggle('scrolled', scrollY > 40);
    const hero = document.querySelector('.page.active > section');
    bar.classList.toggle('show', hero ? hero.getBoundingClientRect().bottom < 80 : scrollY > innerHeight * .6);
  };
  addEventListener('scroll', onScroll, { passive: true });
  onScroll();

  // Desktop nav: sliding highlight
  const navList = document.querySelector('.nav-links');
  const pill = navList.querySelector('.pill');
  const navLinks = [...navList.querySelectorAll('a')];
  const movePill = a => {
    const r = a.getBoundingClientRect(), u = navList.getBoundingClientRect();
    pill.style.width = r.width + 'px';
    pill.style.transform = `translateX(${r.left - u.left - navList.clientLeft}px)`;
    pill.style.opacity = 1;
    navLinks.forEach(l => l.classList.toggle('hl', l === a));
  };
  navLinks.forEach(a => { a.addEventListener('mouseenter', () => movePill(a)); a.addEventListener('focus', () => movePill(a)); });
  navList.addEventListener('mouseleave', () => { pill.style.opacity = 0; navLinks.forEach(l => l.classList.remove('hl')); });

  // Full-screen menu
  const burger = document.querySelector('.burger');
  const menu = document.getElementById('menu');
  const setMenu = open => {
    document.body.classList.toggle('menu-open', open);
    burger.setAttribute('aria-expanded', open);
    burger.setAttribute('aria-label', open ? 'Затвори менюто' : 'Отвори менюто');
    menu.setAttribute('aria-hidden', !open);
  };
  burger.addEventListener('click', () => setMenu(!document.body.classList.contains('menu-open')));
  menu.querySelectorAll('[data-close]').forEach(a => a.addEventListener('click', () => setMenu(false)));
  addEventListener('keydown', e => { if (e.key === 'Escape') setMenu(false); });

  // Marquee: duplicate the group for a seamless loop
  const groups = document.querySelectorAll('#creds .marquee-group');
  if (groups[1]) groups[1].innerHTML = groups[0].innerHTML;

  // Quote: split into words for a reading-style reveal
  const q = document.getElementById('quote-text');
  if (q) q.innerHTML = q.textContent.split(' ').map((w, i) => `<span class="w" style="--i:${i}">${w}</span>`).join(' ');

  // Count-up for years
  const countUp = el => {
    const to = +el.dataset.to;
    if (reduce) { el.textContent = to; return; }
    const start = performance.now(), dur = 1600;
    const tick = now => {
      const p = Math.min((now - start) / dur, 1);
      el.textContent = Math.round(to * (1 - Math.pow(1 - p, 3)));
      if (p < 1) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  };

  // Reveal on scroll
  const io = new IntersectionObserver(entries => entries.forEach(e => {
    if (!e.isIntersecting) return;
    e.target.classList.add('in');
    e.target.querySelectorAll?.('.js-count').forEach(countUp);
    io.unobserve(e.target);
  }), { threshold: .15, rootMargin: '0px 0px -40px 0px' });
  const observeReveals = () => document.querySelectorAll('.page.active [data-reveal]:not(.in), .page.active .quote:not(.in), .page.active .about-photo:not(.in)').forEach(el => io.observe(el));
  observeReveals();

  // Live clocks for London and Sofia
  const clock = tz => new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: tz }).format(new Date());
  const tickClocks = () => {
    document.getElementById('t-lon').textContent = clock('Europe/London');
    document.getElementById('t-sof').textContent = clock('Europe/Sofia');
  };
  if (document.getElementById('t-lon')) { tickClocks(); setInterval(tickClocks, 15000); }

  // Greeting switches between Bulgarian and English
  const greetWords = [...document.querySelectorAll('#greet span')];
  let gi = 0;
  if (!reduce && greetWords.length) setInterval(() => {
    const cur = greetWords[gi]; gi = (gi + 1) % greetWords.length; const next = greetWords[gi];
    cur.classList.remove('on'); cur.classList.add('out');
    next.classList.remove('out'); next.classList.add('on');
    setTimeout(() => cur.classList.remove('out'), 900);
  }, 2600);


  // Latest articles: cards made by build/blog.py. window.POSTS comes with the page; the live site then
  // loads /posts.json, so posts published in the editor appear without rebuilding the site.
  const track = document.getElementById('track'), homeTabs = document.getElementById('home-tabs');
  if (track) {          // only on the home page (other pages don't carry its content)
    const showPosts = data => {
      if (!data || !data.posts) return;
      homeTabs.innerHTML = [`<button class="tab" aria-pressed="true" data-filter="all">${data.all}</button>`,
        ...data.topics.map(t => `<button class="tab" aria-pressed="false" data-filter="${t.id}"></button>`)].join('');
      data.topics.forEach((t, i) => homeTabs.children[i + 1].textContent = t.name);
      track.innerHTML = data.posts.slice(0, 12).map(p => p.card).join('');
      track.querySelectorAll('[data-reveal]').forEach(el => el.removeAttribute('data-reveal'));
      track.scrollTo({ left: 0 });
      requestAnimationFrame(updateProgress);
    };
    homeTabs.addEventListener('click', e => {
      const tab = e.target.closest('.tab');
      if (!tab) return;
      homeTabs.querySelectorAll('.tab').forEach(t => t.setAttribute('aria-pressed', t === tab));
      track.querySelectorAll('.article').forEach(a => a.hidden = tab.dataset.filter !== 'all' && a.dataset.tag !== tab.dataset.filter);
      track.scrollTo({ left: 0 });
      updateProgress();
    });

    const progress = document.getElementById('progress');
    const updateProgress = () => {
      const max = track.scrollWidth - track.clientWidth;
      const ratio = track.clientWidth / track.scrollWidth;
      progress.style.width = (ratio * 100) + '%';
      progress.style.transform = `translateX(${max > 0 ? (track.scrollLeft / max) * (1 / ratio - 1) * 100 : 0}%)`;
    };
    track.addEventListener('scroll', updateProgress, { passive: true });
    addEventListener('resize', updateProgress);
    showPosts(window.POSTS);
    if (location.protocol !== 'file:' && window.SLUGS) fetch('/posts.json').then(r => r.ok ? r.json() : null).then(showPosts).catch(() => {});
    updateProgress();

    document.querySelectorAll('.arrow').forEach(btn => btn.addEventListener('click', () => {
      track.scrollBy({ left: btn.dataset.dir * track.clientWidth * .8, behavior: 'smooth' });
    }));

    // Drag to scroll (mouse)
    let down = false, startX = 0, startLeft = 0, moved = false;
    track.addEventListener('pointerdown', e => {
      if (e.pointerType !== 'mouse') return;
      down = true; moved = false; startX = e.clientX; startLeft = track.scrollLeft;
    });
    addEventListener('pointermove', e => {
      if (!down) return;
      const dx = e.clientX - startX;
      if (Math.abs(dx) > 5) { moved = true; track.classList.add('dragging'); }
      track.scrollLeft = startLeft - dx;
    });
    addEventListener('pointerup', () => { down = false; setTimeout(() => track.classList.remove('dragging'), 0); });
    track.addEventListener('click', e => { if (moved) e.preventDefault(); }, true);
  }


