  // Pages other than the home page don't carry its content; going home from them is a normal page load
  const homeElsewhere = homeEl.hasAttribute('data-elsewhere');
  const titles = { '/': 'д-р Василева – психолог и КПТ психотерапевт' };
  // Addresses: the preview files (opened from disk) use #/ links; the live site uses real paths
  // (/about, and Bulgarian slugs on drvasileva.bg). SLUGS maps a page to its address on this site,
  // OTHER_SLUGS to its address on the other language's site. Only the live build sets SLUGS, so the
  // preview files keep #/ links even when they're put on a web server.
  const HASH_MODE = location.protocol === 'file:' || !window.SLUGS;
  const SLUGS = window.SLUGS || {}, OTHER_SLUGS = window.OTHER_SLUGS || {};
  const KEYS = Object.fromEntries(Object.entries(SLUGS).map(([k, v]) => [v, k]));
  const toUrl = (key, map = SLUGS) => map[key] || key;
  const currentKey = () => {
    if (HASH_MODE) return (location.hash.replace(/^#/, '') || '/').replace(/\/$/, '') || '/';
    const p = decodeURI(location.pathname).replace(/\/(index\.html)?$/, '') || '/';
    return KEYS[p] || p;
  };
  const rewriteLinks = root => root.querySelectorAll('a[href^="#/"]').forEach(a => {
    const key = a.getAttribute('href').slice(1);
    a.dataset.key = key;
    if (!HASH_MODE) a.setAttribute('href', toUrl(key));
  });
  const metaLinks = [...document.querySelectorAll('link[rel="canonical"], link[rel="alternate"][hreflang], meta[property="og:url"]')];
  const metaAttr = m => m.tagName === 'META' ? 'content' : 'href';
  metaLinks.forEach(m => m.dataset.base ||= new URL(m.getAttribute(metaAttr(m))).origin);
  const isBG = document.documentElement.lang === 'bg';
  const syncMeta = key => {
    if (HASH_MODE) return;
    metaLinks.forEach(m => {
      const lang = m.getAttribute('hreflang');
      const map = !lang ? SLUGS : (lang === 'bg') === isBG ? SLUGS : OTHER_SLUGS;
      m.setAttribute(metaAttr(m), m.dataset.base + toUrl(key, map));
    });
  };
  // Language switch: go to the same page in the other language. On a test domain the other language
  // is the same address with or without "-bg" on the first part (test.example.com ↔ test-bg.example.com).
  const LIVE_HOST = /(^|\.)drvasileva\.(co\.uk|bg)$/.test(location.hostname);
  const otherSite = base => HASH_MODE || LIVE_HOST ? base.replace(/\/$/, '')
    : `${location.protocol}//${isBG ? location.host.replace(/^([^.]+)-bg\./, '$1.') : location.host.replace(/^([^.]+)\./, '$1-bg.')}`;
  const syncLang = key => document.querySelectorAll('.lang a[data-base]').forEach(a =>
    a.href = HASH_MODE ? a.dataset.base + location.hash : otherSite(a.dataset.base) + toUrl(key, OTHER_SLUGS));

  // Articles: on the live site the blog's pages are separate files made by build/blog.py. Links to them
  // open with a normal page load, and such a page keeps the content it came with (window.STATIC_PAGE).
  const BLOG = '/articles';
  const isBlog = key => !HASH_MODE && (key === BLOG || key.startsWith(BLOG + '/') || key.startsWith(toUrl(BLOG) + '/'));
  const STATIC = window.STATIC_PAGE;
  const staticHTML = STATIC ? pagesEl.innerHTML : '';
  const staticMeta = metaLinks.map(m => m.getAttribute(metaAttr(m)));
  const onStaticPage = () => STATIC && decodeURI(location.pathname).replace(/\/$/, '') === STATIC.url;
  const showStatic = () => {
    homeEl.classList.remove('active');
    pagesEl.innerHTML = staticHTML;
    const el = pagesEl.firstElementChild;
    rewriteLinks(el);
    wirePage(el);
    document.title = STATIC.title;
    metaLinks.forEach((m, i) => m.setAttribute(metaAttr(m), staticMeta[i]));
    navLinks.forEach(a => a.toggleAttribute('aria-current', a.dataset.key === BLOG));
    document.querySelectorAll('.lang a[data-base]').forEach(a => a.href = otherSite(a.dataset.base) + new URL(STATIC.other).pathname);
    scrollTo({ top: 0, behavior: 'instant' });
    observeReveals();
    onScroll();
  };

  const render = () => {
    if (HASH_MODE && location.hash && !location.hash.startsWith('#/')) return;   // ordinary in-page anchor
    let path = currentKey();
    setMenu(false);
    if (!HASH_MODE && onStaticPage()) return showStatic();
    if (isBlog(path) && !window.NOT_FOUND) return location.reload();     // back to a blog page from another page
    if (path === '/' && homeElsewhere) return location.reload();       // back to the home page
    pagesEl.innerHTML = '';
    // Unknown address: the server's 404 page sets NOT_FOUND; unknown routes also land here
    if (window.NOT_FOUND && HASH_MODE && !location.hash) path = '/404';
    else if (path !== '/' && !PAGES[path]) path = '/404';
    if (path === '/') {
      homeEl.classList.add('active');
    } else {
      homeEl.classList.remove('active');
      const el = document.createElement('div');
      el.className = 'page active';
      el.innerHTML = PAGES[path]();
      pagesEl.appendChild(el);
      rewriteLinks(el);
      wirePage(el);
    }
    const h1 = document.querySelector('.page.active h1');
    document.title = path === '/' ? titles['/'] : `${h1 ? h1.textContent : ''} – д-р Василева`;
    navLinks.forEach(a => a.toggleAttribute('aria-current', !!a.dataset.key && a.dataset.key !== '/' && path.startsWith(a.dataset.key)));
    syncMeta(path);
    syncLang(path);
    scrollTo({ top: 0, behavior: 'instant' });
    observeReveals();
    onScroll();
  };
  // Contact form. TURNSTILE_SITE_KEY is Cloudflare's public test key (always passes); replace it with the real site key at launch.
  const TURNSTILE_SITE_KEY = '0x4AAAAAAFn0BHwXhddLG2qs';
  const FORM_ENDPOINT = '/api/contact';
  function wireForm(el) {
    const form = el.querySelector('#contact-form');
    if (!form) return;
    const err = form.querySelector('.form-error'), btn = form.querySelector('.send'), label = btn.querySelector('.send-label');
    let widget = null;
    // Cloudflare's check is loaded only on the page with the form, not on every page
    if (!window.turnstile && !document.querySelector('script[data-turnstile]')) {
      const ts = document.createElement('script');
      ts.src = 'https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';
      ts.async = true;
      ts.dataset.turnstile = '';
      document.head.appendChild(ts);
    }
    const mountTurnstile = () => {
      if (typeof window.turnstile?.render !== 'function' || !document.body.contains(form)) return false;
      widget = turnstile.render('#ts-box', { sitekey: TURNSTILE_SITE_KEY, theme: 'light', language: 'bg', appearance: 'interaction-only' });
      return true;
    };
    if (!mountTurnstile()) {
      const t = setInterval(() => { if (mountTurnstile() || !document.body.contains(form)) clearInterval(t); }, 300);
    }
    const showError = msg => { err.textContent = msg; err.hidden = false; };
    form.addEventListener('submit', async e => {
      e.preventDefault();
      err.hidden = true;
      form.querySelectorAll('.invalid').forEach(f => f.classList.remove('invalid'));
      const bad = [...form.querySelectorAll('[required]')].filter(f => !f.checkValidity());
      if (bad.length) {
        bad.forEach(f => (f.closest('.field') || f.closest('.check')).classList.add('invalid'));
        bad[0].focus();
        return showError('Моля, попълнете полетата, отбелязани със *.');
      }
      btn.disabled = true; label.textContent = 'Изпращане…';
      const done = () => { form.hidden = true; el.querySelector('.form-done').hidden = false; };
      try {
        if (location.protocol === 'file:') { await new Promise(r => setTimeout(r, 900)); return done(); }   // preview only
        const res = await fetch(FORM_ENDPOINT, { method: 'POST', body: new FormData(form) });
        const data = await res.json().catch(() => ({}));
        if (!res.ok || !data.ok) throw new Error(data.error || 'send');
        done();
      } catch (ex) {
        showError(ex.message === 'verification'
          ? 'Не успяхме да потвърдим, че не сте робот. Моля, опитайте отново.'
          : 'Съжаляваме, нещо се обърка. Моля, опитайте отново или ми се обадете или пишете.');
        if (typeof window.turnstile?.reset === 'function' && widget !== null) turnstile.reset(widget);
      } finally {
        btn.disabled = false; label.textContent = 'Изпратете съобщението';
      }
    });
  }

  function wirePage(el) {
    wireForm(el);
    el.querySelectorAll('.js-count').forEach(c => c.dataset.to = YEARS);
    // Article lists: search, topic, year, type and order, and a "Show more" button after the first cards
    const tabs = el.querySelectorAll('.tab');
    const grid = el.querySelector('[data-per-page]'), more = el.querySelector('.more-btn');
    const tools = el.querySelector('[data-blog-tools]');
    const pick = sel => tools?.querySelector(sel);
    const q = pick('[data-q]'), year = pick('[data-year]'), kind = pick('[data-kind]'), sort = pick('[data-sort]'), clear = pick('[data-clear]');
    const count = el.querySelector('[data-count]'), empty = el.querySelector('[data-empty]');
    const cards = grid ? [...grid.querySelectorAll('.article')] : [];
    const perPage = grid ? +grid.dataset.perPage : Infinity;
    // Search ignores capitals and accents, and finds every word typed, in any order. Words match by their
    // beginning, so other forms of a word are found too ("паника" finds "панически", "attack" finds "attacks").
    const fold = s => s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const words = new Map(cards.map(a => [a, fold(a.dataset.text || a.textContent).split(/[^\p{L}\p{N}]+/u).filter(Boolean)]));
    const stem = w => w.length < 4 ? w : w.slice(0, Math.max(4, w.length - 2));
    const has = (a, w) => words.get(a)?.some(t => t.startsWith(w));
    let shown = perPage;
    const topicNow = () => el.querySelector('.tab[aria-pressed="true"]')?.dataset.filter || 'all';
    const filter = () => {
      const f = topicNow(), typed = fold(q?.value || '').split(/[^\p{L}\p{N}]+/u).filter(Boolean).map(stem);
      const y = year?.value || '', k = kind?.value || '', old = sort?.value === 'old';
      if (grid && sort) {
        const ordered = [...cards].sort((a, b) => (a.dataset.date < b.dataset.date ? -1 : a.dataset.date > b.dataset.date ? 1 : 0) * (old ? 1 : -1));
        grid.append(...ordered);
      }
      let n = 0;
      (grid ? [...grid.querySelectorAll('.article')] : el.querySelectorAll('.article')).forEach(a => {
        const match = (f === 'all' || a.dataset.tag === f) && (!y || a.dataset.year === y) && (!k || a.dataset.kind === k)
          && typed.every(w => has(a, w));
        if (match) n++;
        a.hidden = !match || n > shown;
      });
      if (more) more.hidden = n <= shown;
      if (!tools) return;
      const busy = typed.length || f !== 'all' || y || k || old;
      grid.classList.toggle('filtered', !!busy);         // the big first card only on the plain list
      if (clear) clear.hidden = !q.value;
      if (count) count.textContent = n === 1 ? tools.dataset.countOne : tools.dataset.countMany.replace('{}', n);
      if (empty) empty.hidden = n > 0;
      if (!HASH_MODE) {                                  // the address keeps the choice, so a search can be shared
        const url = new URL(location.href);
        for (const [key, v] of [['q', q?.value.trim()], ['topic', f === 'all' ? '' : f], ['year', y], ['type', k], ['sort', old ? 'old' : '']]) v ? url.searchParams.set(key, v) : url.searchParams.delete(key);
        history.replaceState(history.state, '', url);
      }
    };
    const setTopic = id => tabs.forEach(t => t.setAttribute('aria-pressed', t.dataset.filter === id));
    tabs.forEach(tab => tab.addEventListener('click', () => { setTopic(tab.dataset.filter); shown = perPage; filter(); }));
    more?.addEventListener('click', () => { shown += perPage; filter(); });
    if (tools) {
      const again = () => { shown = perPage; filter(); };
      tools.addEventListener('submit', e => { e.preventDefault(); q.blur(); });
      q.addEventListener('input', again);
      [year, kind, sort].forEach(s => s?.addEventListener('change', again));
      clear?.addEventListener('click', () => { q.value = ''; again(); q.focus(); });
      el.querySelector('[data-reset]')?.addEventListener('click', () => {
        q.value = ''; [year, kind].forEach(s => s && (s.value = '')); if (sort) sort.value = 'new'; setTopic('all'); again();
      });
      const params = new URLSearchParams(location.search);       // a shared search opens as it was
      if (params.get('q')) q.value = params.get('q');
      const set = (s, v) => { if (s && v && [...s.options].some(o => o.value === v)) s.value = v; };
      set(year, params.get('year')); set(kind, params.get('type')); set(sort, params.get('sort'));
      if (params.get('topic') && [...tabs].some(t => t.dataset.filter === params.get('topic'))) setTopic(params.get('topic'));
    }
    if (grid) filter();
    el.querySelectorAll('[data-copy]').forEach(b => b.addEventListener('click', () =>
      navigator.clipboard?.writeText(b.dataset.copy).then(() => { b.classList.add('done'); b.setAttribute('aria-label', b.dataset.done); })));
  }
  rewriteLinks(document);
  const navigated = () => { document.documentElement.classList.add('navigated'); render(); };
  if (HASH_MODE) {
    addEventListener('hashchange', navigated);
  } else {
    // Real addresses: follow internal links without reloading, and support the back button
    addEventListener('popstate', navigated);
    document.addEventListener('click', e => {
      const a = e.target.closest('a[data-key]');
      if (!a || isBlog(a.dataset.key) || (a.dataset.key === '/' && homeElsewhere) || e.defaultPrevented || e.button || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || a.target) return;
      e.preventDefault();
      if (a.getAttribute('href') !== location.pathname) history.pushState(null, '', a.getAttribute('href'));
      navigated();
    });
  }
  render();
